import{_ as e,o as a,c as s,a2 as d}from"./chunks/framework.DZhUhjDB.js";const u=JSON.parse('{"title":"Seguridad Operacional","description":"Seguridad Operacional","frontmatter":{"title":"Seguridad Operacional","description":"Seguridad Operacional"},"headers":[],"relativePath":"roles/blue-team/seguridad-operacional.md","filePath":"roles/blue-team/seguridad-operacional.md","lastUpdated":1787529976000}'),i={name:"roles/blue-team/seguridad-operacional.md"};function r(o,t,n,l,c,g){return a(),s("div",null,[...t[0]||(t[0]=[d(`<div align="center"><h1 id="🛡️-seguridad-operacional" tabindex="-1">🛡️ Seguridad Operacional</h1><p><strong>CISSP Domain · Security Operations</strong></p><p><em>&quot;El día a día que mantiene viva la seguridad — sin glamour, con disciplina.&quot;</em></p><p><img src="https://img.shields.io/badge/tier%20salarial-C%2FB-blue" alt="Tier"> <img src="https://img.shields.io/badge/demanda-estable-green" alt="Demanda"> <img src="https://img.shields.io/badge/entry%20level-amigable-success" alt="Entry"></p></div><hr><h2 id="📋-descripcion" tabindex="-1">📋 Descripción</h2><p>Disciplina del <strong>BAU (Business As Usual) de seguridad</strong>: gobernanza operativa, gestión de riesgos día a día, continuidad de negocio, gestión de cambios, incident management coordinado y métricas. Es donde la estrategia del CISO se traduce en procesos reales que ejecutan equipos.</p><p>No es la rama más &quot;sexy&quot; del menú, pero es la que <strong>asegura que todo lo demás funcione</strong> — sin SecOps, los hallazgos del red team mueren en una hoja de Excel.</p><hr><h2 id="👤-roles-tipicos" tabindex="-1">👤 Roles típicos</h2><ul><li><strong>Security Operations Manager</strong> — coordinación SOC, métricas, escalamiento</li><li><strong>GRC Analyst</strong> — gestión de riesgos, controles, evidencias</li><li><strong>Security Coordinator / PMO</strong> — proyectos transversales de seguridad</li><li><strong>BCMS Coordinator</strong> — continuidad de negocio (ISO 22301)</li><li><strong>Change Advisory Board (CAB) Security</strong> — review de cambios desde seguridad</li></ul><hr><h2 id="🛠️-stack-y-herramientas" tabindex="-1">🛠️ Stack y herramientas</h2><table tabindex="0"><thead><tr><th>Categoría</th><th>Herramientas</th></tr></thead><tbody><tr><td><strong>GRC platforms</strong></td><td>ServiceNow GRC · Archer (RSA) · OneTrust · MetricStream · Hyperproof</td></tr><tr><td><strong>ITSM / CMDB</strong></td><td>ServiceNow · Jira Service Mgmt · BMC Helix · Freshservice</td></tr><tr><td><strong>Risk registers</strong></td><td>Excel/Sheets · LogicGate · Resolver · Riskonnect</td></tr><tr><td><strong>BCM / DR</strong></td><td>Fusion Risk Mgmt · Veoci · Castellan</td></tr><tr><td><strong>Documentation</strong></td><td>Confluence · Notion · SharePoint</td></tr><tr><td><strong>Métricas SOC</strong></td><td>Power BI · Grafana · Splunk dashboards · Tableau</td></tr><tr><td><strong>Pentest tracking</strong></td><td>Defectdojo · Faraday · PlexTrac</td></tr></tbody></table><hr><h2 id="🎓-certificaciones-recomendadas" tabindex="-1">🎓 Certificaciones recomendadas</h2><table tabindex="0"><thead><tr><th>Nivel</th><th>Certificación</th><th>Vendor</th><th>Costo (USD)</th><th>Notas</th></tr></thead><tbody><tr><td>Entry</td><td>ITIL 4 Foundation</td><td>AXELOS</td><td>~$200</td><td>Procesos base</td></tr><tr><td>Entry</td><td>CompTIA Security+</td><td>CompTIA</td><td>~$400</td><td>Conceptos generales</td></tr><tr><td>Mid</td><td>CISM</td><td>ISACA</td><td>~$760</td><td>Estrella de SecOps Mgmt</td></tr><tr><td>Mid</td><td>CRISC</td><td>ISACA</td><td>~$760</td><td>Risk-focused</td></tr><tr><td>Mid</td><td>ISO 22301 LI</td><td>PECB / Bureau Veritas</td><td>~$1,200</td><td>Continuidad</td></tr><tr><td>Senior</td><td>CISSP</td><td>(ISC)²</td><td>~$750</td><td>Estratégico</td></tr><tr><td>Senior</td><td>CGEIT</td><td>ISACA</td><td>~$760</td><td>Gobernanza IT</td></tr></tbody></table><hr><h2 id="🗺️-roadmap-12-meses" tabindex="-1">🗺️ Roadmap (12 meses)</h2><h3 id="fase-1-—-fundamentos-0-3-meses" tabindex="-1">Fase 1 — Fundamentos (0-3 meses)</h3><ul><li>[ ] ITIL 4 Foundation aprobado</li><li>[ ] Marco NIST CSF 2.0 leído y mapeado a tu org</li><li>[ ] Construir un risk register simple (Excel o Notion)</li><li>[ ] Plantillas de RACI, RCA y change management</li></ul><h3 id="fase-2-—-especializacion-3-6-meses" tabindex="-1">Fase 2 — Especialización (3-6 meses)</h3><ul><li>[ ] Diseñar un BIA (Business Impact Analysis) para 3 procesos críticos</li><li>[ ] Tabletop exercise documentado (escenario ransomware)</li><li>[ ] Métricas SOC: MTTD, MTTR, FP rate, ATT&amp;CK coverage</li><li>[ ] CISM o CRISC empezado</li></ul><h3 id="fase-3-—-profesional-6-12-meses" tabindex="-1">Fase 3 — Profesional (6-12 meses)</h3><ul><li>[ ] Implementar SGSI ligero basado en ISO 27001 (declaración SoA)</li><li>[ ] Construir dashboard ejecutivo de seguridad (Power BI / Grafana)</li><li>[ ] Liderar 1 simulacro de continuidad de negocio</li><li>[ ] CISM aprobado</li></ul><hr><h2 id="💰-salarios-en-colombia-usd-mes" tabindex="-1">💰 Salarios en Colombia (USD/mes)</h2><table tabindex="0"><thead><tr><th>Nivel</th><th>Local 🇨🇴</th><th>Remoto 🌎</th><th>Notas</th></tr></thead><tbody><tr><td>Junior (0-2 años)</td><td>$500 - $1,100</td><td>$1,000 - $2,000</td><td>GRC entry-level abundante</td></tr><tr><td>Mid (2-5 años)</td><td>$1,300 - $2,800</td><td>$2,500 - $4,500</td><td>CISM duplica el rango</td></tr><tr><td>Senior (5+ años)</td><td>$3,000 - $6,000</td><td>$5,000 - $9,000</td><td>Líder de SecOps en banca = top</td></tr></tbody></table><blockquote><p><strong>Tip:</strong> dominio de inglés escrito + certificación CISM/CRISC = mayor multiplicador en LATAM remoto.</p></blockquote><hr><h2 id="🔗-conexion-con-otras-ramas" tabindex="-1">🔗 Conexión con otras ramas</h2><ul><li><strong><code>grc-compliance</code></strong> → solapamiento ~70%, son primos hermanos</li><li><strong><code>risk-manager</code></strong> <em>(02)</em> → mismo lenguaje de riesgo</li><li><strong><code>business-continuity-manager</code></strong> <em>(02)</em> → BCM como subdisciplina</li><li><strong><code>ciso</code></strong> <em>(02)</em> → SecOps Manager es el siguiente escalón</li><li><strong><code>analista-soc</code></strong> → tu output diario son sus alertas</li></ul><hr><h2 id="📂-estructura" tabindex="-1">📂 Estructura</h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>seguridad-operacional/</span></span>
<span class="line"><span>├── herramientas/    # Plantillas GRC, dashboards, RACI, change forms</span></span>
<span class="line"><span>├── recursos/        # ITIL, NIST CSF, ISO 27001/22301 cheatsheets</span></span>
<span class="line"><span>├── laboratorios/    # Risk register de prueba, BIA template</span></span>
<span class="line"><span>└── casos-uso/       # Tabletops, post-mortems, métricas reales</span></span></code></pre></div><hr><div align="center"><p><strong><a href="./../README">⬅ Volver a Ciberseguridad</a></strong></p></div>`,34)])])}const m=e(i,[["render",r]]);export{u as __pageData,m as default};
